INSERT INTO functional_category (category_name, description) VALUES ('Perception & Encoding','How biological and artificial systems transform raw sensory input into structured internal representations.');
INSERT INTO functional_category (category_name, description) VALUES ('Attention & Selectivity','Mechanisms by which biological and artificial systems selectively focus computational resources on relevant information.');
INSERT INTO functional_category (category_name, description) VALUES ('Memory & Storage','How information is retained, consolidated, and retrieved across short and long timescales in brains and networks.');
INSERT INTO functional_category (category_name, description) VALUES ('Learning & Adaptation','The synaptic and algorithmic rules by which biological and artificial systems update their internal parameters from experience.');
INSERT INTO functional_category (category_name, description) VALUES ('Decision & Prediction','How brains and models compute expectations, evaluate outcomes, and select actions under uncertainty.');
INSERT INTO functional_category (category_name, description) VALUES ('Output & Generation','How biological motor systems and artificial generative models produce structured sequential outputs.');
INSERT INTO biological_structure (bio_name, bio_type, description, brain_location) VALUES ('Primary Visual Cortex (V1)','Brain Region','The first cortical region to process visual information. Contains simple and complex cells with oriented receptive fields that detect edges, spatial frequencies, and orientations.','Occipital lobe');
INSERT INTO biological_structure (bio_name, bio_type, description, brain_location) VALUES ('Inferior Temporal Cortex (IT)','Brain Region','The apex of the ventral visual stream, encoding high-level object representations invariant to position, size, and viewpoint.','Temporal lobe');
INSERT INTO biological_structure (bio_name, bio_type, description, brain_location) VALUES ('Ventral Visual Stream','Neural Circuit','A hierarchical sequence of cortical areas (V1 to V2 to V4 to IT) that progressively transforms pixel-level input into abstract object representations used for recognition.','Occipital to temporal lobe');
INSERT INTO biological_structure (bio_name, bio_type, description, brain_location) VALUES ('Sparse Coding in V1','Cognitive Mechanism','The empirically observed tendency of V1 neurons to respond selectively to specific stimuli with only a small fraction active at any time, maximizing information transmission efficiency.','Occipital lobe');
INSERT INTO biological_structure (bio_name, bio_type, description, brain_location) VALUES ('Hippocampus','Brain Region','Critical for encoding new episodic and declarative memories. Operates as a fast-learning system that indexes neocortical memory traces and supports memory consolidation during sleep.','Medial temporal lobe');
INSERT INTO biological_structure (bio_name, bio_type, description, brain_location) VALUES ('Sleep Replay (REM/NREM)','Cognitive Mechanism','During sleep, neural activity patterns from recent experiences are replayed in compressed form. This consolidates memories from hippocampus to neocortex and prevents interference between memories.','Hippocampus and Neocortex');
INSERT INTO biological_structure (bio_name, bio_type, description, brain_location) VALUES ('Neocortex','Brain Region','The slow-learning long-term memory system. Organized in cortical columns and layers; gradually consolidates knowledge from the hippocampus through repeated replay.','Cerebral cortex');
INSERT INTO biological_structure (bio_name, bio_type, description, brain_location) VALUES ('Synaptic Plasticity (STDP)','Cellular Process','Spike-timing-dependent plasticity: synaptic weights change based on the precise timing difference between pre- and post-synaptic firing. The biological implementation of Hebbian learning.','Cortex and hippocampus');
INSERT INTO biological_structure (bio_name, bio_type, description, brain_location) VALUES ('Hebbian Learning','Cellular Process','The principle that neurons that fire together wire together. Synapses strengthen when pre- and post-synaptic neurons are co-active. The foundational biological learning rule.','Cortex-wide');
INSERT INTO biological_structure (bio_name, bio_type, description, brain_location) VALUES ('Prefrontal Cortex (PFC)','Brain Region','Orchestrates executive function, working memory, and top-down attentional control. Selects which information from posterior cortices receives processing priority.','Frontal lobe');
INSERT INTO biological_structure (bio_name, bio_type, description, brain_location) VALUES ('Cortico-Thalamic Circuit','Neural Circuit','Reciprocal loops between cortex and thalamus that implement gating of sensory information and regulation of attention across the cortex through parallel functional channels.','Cortex and thalamus');
INSERT INTO biological_structure (bio_name, bio_type, description, brain_location) VALUES ('Parietal Cortex','Brain Region','Integrates sensory information with spatial and context signals. Works with PFC to implement exogenous attention and spatial working memory.','Parietal lobe');
INSERT INTO biological_structure (bio_name, bio_type, description, brain_location) VALUES ('Dopaminergic System','Neurotransmitter System','Midbrain dopamine neurons signal reward prediction errors: firing when reward exceeds expectation and pausing when reward is omitted. A biological teaching signal for reinforcement learning.','Midbrain VTA and substantia nigra');
INSERT INTO biological_structure (bio_name, bio_type, description, brain_location) VALUES ('Basal Ganglia','Brain Region','A subcortical network involved in action selection, reward-based learning, and habit formation. Receives dopaminergic prediction error signals and updates action values accordingly.','Subcortical nuclei');
INSERT INTO biological_structure (bio_name, bio_type, description, brain_location) VALUES ('Primary Motor Cortex (M1)','Brain Region','Generates sequential motor commands for voluntary movement. Population-level dynamics encode both movement preparation and execution as trajectories through a high-dimensional state space.','Frontal lobe');
INSERT INTO biological_structure (bio_name, bio_type, description, brain_location) VALUES ('Predictive Coding Hierarchy','Cognitive Mechanism','A theory of cortical computation in which each level predicts the activity of the level below, sending only prediction errors upward. Minimizes surprise across the cortical hierarchy.','Cortex-wide');
INSERT INTO artificial_structure (art_name, art_type, description, architecture_family) VALUES ('Convolutional Neural Network (CNN)','Architecture Component','A feedforward network applying learned filter kernels hierarchically across spatial inputs. Lower layers detect edges; deeper layers encode complex object parts and categories.','CNN');
INSERT INTO artificial_structure (art_name, art_type, description, architecture_family) VALUES ('Hierarchical Deep Network Layers','Layer Type','The stacked layer structure of deep networks where each successive layer computes increasingly abstract representations, mirroring the progressive abstraction of cortical hierarchies.','CNN / Deep Learning');
INSERT INTO artificial_structure (art_name, art_type, description, architecture_family) VALUES ('Sparse Autoencoder','Architecture Component','A neural network trained to reconstruct its input through a bottleneck with a sparsity constraint on activations. Encourages each unit to respond selectively to specific input features.','Autoencoder');
INSERT INTO artificial_structure (art_name, art_type, description, architecture_family) VALUES ('Dropout Regularization','Training Mechanism','A training technique that randomly sets neuron activations to zero during forward passes, producing sparse distributed representations and preventing co-adaptation of features.','General Deep Learning');
INSERT INTO artificial_structure (art_name, art_type, description, architecture_family) VALUES ('Long Short-Term Memory (LSTM)','Memory Module','A recurrent network architecture with gating mechanisms that selectively retain or discard information over long sequences, enabling long-range temporal dependencies.','RNN');
INSERT INTO artificial_structure (art_name, art_type, description, architecture_family) VALUES ('Continual Learning with Replay','Algorithm','A family of algorithms that store or regenerate examples of past tasks and interleave them with new training to prevent catastrophic forgetting. Computationally mirrors sleep memory replay.','Continual Learning');
INSERT INTO artificial_structure (art_name, art_type, description, architecture_family) VALUES ('Attention Head (Transformer)','Attention Mechanism','A component in transformer architectures that computes weighted sums over input positions using query-key-value dot products, allowing the model to focus on relevant context positions.','Transformer');
INSERT INTO artificial_structure (art_name, art_type, description, architecture_family) VALUES ('Multi-Head Self-Attention','Attention Mechanism','Multiple attention heads operating in parallel, each attending to different aspects of the input. The parallel structure mirrors the multiple functional channels in cortico-thalamic circuits.','Transformer');
INSERT INTO artificial_structure (art_name, art_type, description, architecture_family) VALUES ('Backpropagation','Training Mechanism','The algorithm used to compute gradients of the loss function with respect to all network weights by propagating error signals backward through the network.','General Deep Learning');
INSERT INTO artificial_structure (art_name, art_type, description, architecture_family) VALUES ('Plastic Synaptic Weights','Training Mechanism','Network weights that change through Hebbian-like fast-learning rules during inference, allowing within-episode adaptation without full retraining. Inspired by biological synaptic plasticity.','Meta-Learning');
INSERT INTO artificial_structure (art_name, art_type, description, architecture_family) VALUES ('Temporal Difference (TD) Learning','Algorithm','A reinforcement learning algorithm that updates value estimates based on the difference between successive predictions. The mathematical formalization of reward prediction error signaling.','Reinforcement Learning');
INSERT INTO artificial_structure (art_name, art_type, description, architecture_family) VALUES ('Variational Autoencoder (VAE)','Architecture Component','A generative model that encodes inputs into a probabilistic latent space and decodes samples from it. Implements approximate Bayesian inference, formally parallel to predictive coding.','Generative Model');
INSERT INTO artificial_structure (art_name, art_type, description, architecture_family) VALUES ('Predictive Coding Network','Architecture Component','A hierarchical network where each layer generates predictions for the layer below and only prediction errors propagate upward. A direct computational implementation of the predictive coding theory.','Predictive Coding');
INSERT INTO artificial_structure (art_name, art_type, description, architecture_family) VALUES ('Sequence-to-Sequence RNN','Architecture Component','A recurrent network that encodes an input sequence into a fixed-dimensional state and decodes it into an output sequence. Used in language, speech, and motor sequence generation tasks.','RNN');
INSERT INTO artificial_structure (art_name, art_type, description, architecture_family) VALUES ('Recurrent Neural Network (RNN)','Architecture Component','A class of networks with recurrent connections that maintain an internal state across time steps, enabling the modeling of temporal dynamics and sequential structure.','RNN');
