INSERT INTO parallel (bio_id, art_id, category_id, parallel_name, parallel_type, design_insight, confidence_level) SELECT b.bio_id, a.art_id, c.category_id, 'V1 Simple Cells and Convolutional Filters', 'Structural', 'V1 simple cells detect oriented edges through localized linear filters arranged hierarchically. CNNs independently converged on the same solution. This structural identity confirms that edge detection via learned spatial filters is an optimal strategy for visual encoding. Deeper cortical areas (V2, V4, IT) could template the design of the remaining CNN layers more precisely.', 'High' FROM biological_structure b, artificial_structure a, functional_category c WHERE b.bio_name = 'Primary Visual Cortex (V1)' AND a.art_name = 'Convolutional Neural Network (CNN)' AND c.category_name = 'Perception & Encoding';
INSERT INTO parallel (bio_id, art_id, category_id, parallel_name, parallel_type, design_insight, confidence_level) SELECT b.bio_id, a.art_id, c.category_id, 'Sparse Coding in V1 and Sparse Autoencoders', 'Computational', 'V1 maintains a sparse code: at any moment only 1-5% of neurons are active, maximizing information capacity. Sparse autoencoders replicate this constraint artificially. The biological solution suggests sparsity should be a fundamental design principle rather than optional regularization.', 'High' FROM biological_structure b, artificial_structure a, functional_category c WHERE b.bio_name = 'Sparse Coding in V1' AND a.art_name = 'Sparse Autoencoder' AND c.category_name = 'Perception & Encoding';
INSERT INTO parallel (bio_id, art_id, category_id, parallel_name, parallel_type, design_insight, confidence_level) SELECT b.bio_id, a.art_id, c.category_id, 'Ventral Stream Hierarchy and Deep Network Layer Stack', 'Structural', 'The ventral stream processes information through progressively abstract levels: edges in V1, textures in V2, shapes in V4, objects in IT. Deep networks mirror this exactly. AI should investigate whether replicating the biological inter-area connectivity patterns yields representational advantages over current architectures.', 'High' FROM biological_structure b, artificial_structure a, functional_category c WHERE b.bio_name = 'Ventral Visual Stream' AND a.art_name = 'Hierarchical Deep Network Layers' AND c.category_name = 'Perception & Encoding';
INSERT INTO parallel (bio_id, art_id, category_id, parallel_name, parallel_type, design_insight, confidence_level) SELECT b.bio_id, a.art_id, c.category_id, 'V1 Lateral Inhibition and Dropout Regularization', 'Computational', 'Lateral inhibition in V1 enforces sparse coding by suppressing co-active neurons. Dropout achieves a statistically similar effect by randomly zeroing activations. However biological sparsity is structured and stimulus-specific, not random. Structured stimulus-conditioned dropout could outperform random dropout as a regularization strategy.', 'Medium' FROM biological_structure b, artificial_structure a, functional_category c WHERE b.bio_name = 'Sparse Coding in V1' AND a.art_name = 'Dropout Regularization' AND c.category_name = 'Perception & Encoding';
INSERT INTO parallel (bio_id, art_id, category_id, parallel_name, parallel_type, design_insight, confidence_level) SELECT b.bio_id, a.art_id, c.category_id, 'Hippocampal Gating and LSTM Gates', 'Functional', 'The hippocampus gates what enters long-term memory using pattern separation and pattern completion circuits. The LSTM replicates this functional role via input and forget gates. A complementary learning systems architecture with separate fast and slow memory networks operating simultaneously would better reflect the biology.', 'Medium' FROM biological_structure b, artificial_structure a, functional_category c WHERE b.bio_name = 'Hippocampus' AND a.art_name = 'Long Short-Term Memory (LSTM)' AND c.category_name = 'Memory & Storage';
INSERT INTO parallel (bio_id, art_id, category_id, parallel_name, parallel_type, design_insight, confidence_level) SELECT b.bio_id, a.art_id, c.category_id, 'Biological Sleep Replay and Artificial Memory Replay', 'Functional', 'During sleep the hippocampus replays compressed memory traces to the neocortex enabling knowledge consolidation without overwriting old memories. Continual learning with replay implements the same principle. Key insight: biological replay is generative, compressed, and hierarchically organized. AI systems should use generative replay rather than stored exemplars.', 'High' FROM biological_structure b, artificial_structure a, functional_category c WHERE b.bio_name = 'Sleep Replay (REM/NREM)' AND a.art_name = 'Continual Learning with Replay' AND c.category_name = 'Memory & Storage';
INSERT INTO parallel (bio_id, art_id, category_id, parallel_name, parallel_type, design_insight, confidence_level) SELECT b.bio_id, a.art_id, c.category_id, 'Hippocampal Indexing Theory and Replay-Based Continual Learning', 'Functional', 'The hippocampal indexing theory proposes that the hippocampus stores pointers to distributed neocortical representations. Replay-based continual learning uses stored or generated memories to prevent catastrophic forgetting. The biological system stores compressed indices, not raw data. AI architectures should implement compressed latent-space replay to match biological efficiency.', 'High' FROM biological_structure b, artificial_structure a, functional_category c WHERE b.bio_name = 'Hippocampus' AND a.art_name = 'Continual Learning with Replay' AND c.category_name = 'Memory & Storage';
INSERT INTO parallel (bio_id, art_id, category_id, parallel_name, parallel_type, design_insight, confidence_level) SELECT b.bio_id, a.art_id, c.category_id, 'Spike-Timing-Dependent Plasticity and Backpropagation', 'Computational', 'STDP adjusts synaptic weights based on the relative timing of pre- and post-synaptic spikes in a local biologically plausible manner. Backpropagation requires a global error signal (the weight transport problem). Both achieve similar learning outcomes. Designing local learning rules that approximate backpropagation gradients without global error propagation is the critical open problem this parallel identifies.', 'High' FROM biological_structure b, artificial_structure a, functional_category c WHERE b.bio_name = 'Synaptic Plasticity (STDP)' AND a.art_name = 'Backpropagation' AND c.category_name = 'Learning & Adaptation';
INSERT INTO parallel (bio_id, art_id, category_id, parallel_name, parallel_type, design_insight, confidence_level) SELECT b.bio_id, a.art_id, c.category_id, 'Hebbian Plasticity and Differentiable Plastic Weights', 'Computational', 'Hebbian learning is the biological rule for rapid experience-dependent synaptic change. Differentiable plasticity implements Hebbian-like fast weights that change during a forward pass without gradient descent, enabling within-episode adaptation. This points toward a two-timescale architecture: slow meta-learning via gradient descent and fast Hebbian adaptation during inference.', 'High' FROM biological_structure b, artificial_structure a, functional_category c WHERE b.bio_name = 'Hebbian Learning' AND a.art_name = 'Plastic Synaptic Weights' AND c.category_name = 'Learning & Adaptation';
INSERT INTO parallel (bio_id, art_id, category_id, parallel_name, parallel_type, design_insight, confidence_level) SELECT b.bio_id, a.art_id, c.category_id, 'Dopamine Prediction Error and Temporal Difference Learning', 'Computational', 'This is the most precisely established parallel in neuro-AI. Dopamine neurons fire exactly as the TD error signal predicts: phasic activation for unexpected reward, silence for predicted reward, pause for omitted reward. The mathematical identity is virtually certain. The design insight: the biological system is remarkably energy-efficient. AI could adopt biologically realistic sparse event-driven TD updates instead of dense synchronous updates.', 'High' FROM biological_structure b, artificial_structure a, functional_category c WHERE b.bio_name = 'Dopaminergic System' AND a.art_name = 'Temporal Difference (TD) Learning' AND c.category_name = 'Decision & Prediction';
INSERT INTO parallel (bio_id, art_id, category_id, parallel_name, parallel_type, design_insight, confidence_level) SELECT b.bio_id, a.art_id, c.category_id, 'Basal Ganglia Reward Circuit and TD Reinforcement Learning', 'Structural', 'The basal ganglia implements action selection through anatomically distinct direct and indirect pathways that parallel the go/no-go logic of RL action selection. AI RL architectures could adopt the biologically separate direct and indirect pathway design to create more efficient action gating, particularly for sparse reward environments.', 'High' FROM biological_structure b, artificial_structure a, functional_category c WHERE b.bio_name = 'Basal Ganglia' AND a.art_name = 'Temporal Difference (TD) Learning' AND c.category_name = 'Decision & Prediction';
INSERT INTO parallel (bio_id, art_id, category_id, parallel_name, parallel_type, design_insight, confidence_level) SELECT b.bio_id, a.art_id, c.category_id, 'Predictive Coding Cortical Hierarchy and Variational Autoencoders', 'Computational', 'Predictive coding proposes the cortex maintains generative models of sensory input, sending predictions downward and only propagating prediction errors upward. Variational autoencoders implement formally identical Bayesian inference. Implementing VAE inference as a local continuous-time predictive coding process could yield a more biologically plausible and energy-efficient generative model.', 'Medium' FROM biological_structure b, artificial_structure a, functional_category c WHERE b.bio_name = 'Predictive Coding Hierarchy' AND a.art_name = 'Variational Autoencoder (VAE)' AND c.category_name = 'Decision & Prediction';
INSERT INTO parallel (bio_id, art_id, category_id, parallel_name, parallel_type, design_insight, confidence_level) SELECT b.bio_id, a.art_id, c.category_id, 'Cortical Predictive Coding and Predictive Coding Networks', 'Structural', 'Predictive Coding Networks directly implement the neuroscientific theory of cortical computation. Each layer maintains both a representation and a prediction of the layer below, with only error units propagating upward. The design advantage: such networks can learn in an unsupervised and online manner without backpropagation because the local prediction error is the training signal at every layer simultaneously.', 'High' FROM biological_structure b, artificial_structure a, functional_category c WHERE b.bio_name = 'Predictive Coding Hierarchy' AND a.art_name = 'Predictive Coding Network' AND c.category_name = 'Decision & Prediction';
INSERT INTO parallel (bio_id, art_id, category_id, parallel_name, parallel_type, design_insight, confidence_level) SELECT b.bio_id, a.art_id, c.category_id, 'Cortico-Thalamic Attention Gating and Multi-Head Self-Attention', 'Structural', 'The cortico-thalamic loop implements attention by selectively amplifying or suppressing thalamic relay of sensory signals through multiple parallel channels. Multi-head self-attention implements a structurally analogous parallel gating mechanism. Thalamic gating is modulated by neuromodulators to switch between exploration and exploitation modes. AI attention heads have no equivalent modulation mechanism.', 'Medium' FROM biological_structure b, artificial_structure a, functional_category c WHERE b.bio_name = 'Cortico-Thalamic Circuit' AND a.art_name = 'Multi-Head Self-Attention' AND c.category_name = 'Attention & Selectivity';
INSERT INTO parallel (bio_id, art_id, category_id, parallel_name, parallel_type, design_insight, confidence_level) SELECT b.bio_id, a.art_id, c.category_id, 'Prefrontal Top-Down Attention and Transformer Attention Heads', 'Functional', 'The PFC implements top-down attentional control by biasing activity in sensory cortices toward task-relevant features. Transformer attention heads implement a learned weighting over input positions that serves a functionally equivalent role. The biological system uses anatomically distinct bottom-up and top-down attention pathways. Designing separate bottom-up and top-down attention modules reflecting the PFC-parietal distinction could improve task-directed attention in AI.', 'High' FROM biological_structure b, artificial_structure a, functional_category c WHERE b.bio_name = 'Prefrontal Cortex (PFC)' AND a.art_name = 'Attention Head (Transformer)' AND c.category_name = 'Attention & Selectivity';
INSERT INTO parallel (bio_id, art_id, category_id, parallel_name, parallel_type, design_insight, confidence_level) SELECT b.bio_id, a.art_id, c.category_id, 'Parietal Spatial Attention and Positional Attention in Transformers', 'Functional', 'The parietal cortex implements a dynamic spatial saliency map directing processing resources to behaviorally relevant locations. Transformer attention heads compute position-weighted representations with positional encodings. Implementing a biologically realistic dynamic saliency map rather than static positional encodings could improve spatial reasoning in vision transformers.', 'Medium' FROM biological_structure b, artificial_structure a, functional_category c WHERE b.bio_name = 'Parietal Cortex' AND a.art_name = 'Attention Head (Transformer)' AND c.category_name = 'Attention & Selectivity';
INSERT INTO parallel (bio_id, art_id, category_id, parallel_name, parallel_type, design_insight, confidence_level) SELECT b.bio_id, a.art_id, c.category_id, 'Neocortical Columnar Organization and Deep Layer Hierarchy', 'Structural', 'The neocortex organizes knowledge in cortical columns spanning all 6 layers with lateral connections between columns encoding relationships. Deep networks use horizontal layer stacking without the vertical columnar organization. Implementing a columnar architecture with feature-specific columns and lateral inter-column connections could provide more structured and interpretable representations.', 'Medium' FROM biological_structure b, artificial_structure a, functional_category c WHERE b.bio_name = 'Neocortex' AND a.art_name = 'Hierarchical Deep Network Layers' AND c.category_name = 'Memory & Storage';
INSERT INTO parallel (bio_id, art_id, category_id, parallel_name, parallel_type, design_insight, confidence_level) SELECT b.bio_id, a.art_id, c.category_id, 'Motor Cortex Population Dynamics and Sequence-to-Sequence RNNs', 'Functional', 'Motor cortex generates sequential motor commands as trajectories through a high-dimensional population state space. The population activity rotates through a manifold during movement. Seq2Seq RNNs encode-then-decode sequential outputs through a similarly high-dimensional hidden state. Explicitly constraining RNN hidden state trajectories to lie on low-dimensional rotational manifolds could produce smoother more energy-efficient sequence generation.', 'Medium' FROM biological_structure b, artificial_structure a, functional_category c WHERE b.bio_name = 'Primary Motor Cortex (M1)' AND a.art_name = 'Sequence-to-Sequence RNN' AND c.category_name = 'Output & Generation';
INSERT INTO parallel (bio_id, art_id, category_id, parallel_name, parallel_type, design_insight, confidence_level) SELECT b.bio_id, a.art_id, c.category_id, 'Motor Cortex Recurrent Dynamics and Recurrent Neural Networks', 'Structural', 'Primary motor cortex contains dense recurrent excitatory connections between pyramidal neurons that sustain activity across time. RNNs implement recurrence through explicit feedback connections. The biological network uses excitatory and inhibitory neurons in approximately 80:20 ratio with structured connectivity. Structuring RNN connectivity to reflect the biological E/I balance could improve temporal stability and reduce vanishing gradient problems.', 'Medium' FROM biological_structure b, artificial_structure a, functional_category c WHERE b.bio_name = 'Primary Motor Cortex (M1)' AND a.art_name = 'Recurrent Neural Network (RNN)' AND c.category_name = 'Output & Generation';
INSERT INTO parallel (bio_id, art_id, category_id, parallel_name, parallel_type, design_insight, confidence_level) SELECT b.bio_id, a.art_id, c.category_id, 'Prefrontal Working Memory and Multi-Head Attention Context Window', 'Structural', 'The prefrontal cortex maintains a limited-capacity working memory buffer held in active neural representations through sustained firing. The transformer context window is the functional equivalent. Biological working memory is an active dynamically updated representation regulated by dopamine and norepinephrine. Implementing neuromodulatory gating of the attention context where certain tokens are actively maintained or suppressed based on task relevance mirrors the biological reality of PFC working memory.', 'High' FROM biological_structure b, artificial_structure a, functional_category c WHERE b.bio_name = 'Prefrontal Cortex (PFC)' AND a.art_name = 'Multi-Head Self-Attention' AND c.category_name = 'Attention & Selectivity';
