INSERT INTO paper (title, publication_year, journal, doi, methodology_type, ai_architecture_ref, keywords, abstract_summary) VALUES ('Performance-optimized hierarchical models predict neural responses in higher visual cortex',2014,'Proceedings of the National Academy of Sciences','10.1073/pnas.1403112111','Computational','CNN','visual cortex, CNN, ventral stream, neural responses, hierarchical models','Demonstrates that task-optimized CNNs predict neural activity in primate visual cortical areas V4 and IT, establishing the quantitative equivalence between deep network representations and biological visual processing.');
INSERT INTO paper (title, publication_year, journal, doi, methodology_type, ai_architecture_ref, keywords, abstract_summary) VALUES ('Deep Neural Networks Rival the Representation of Primate IT Cortex for Core Visual Object Recognition',2014,'PLOS Computational Biology','10.1371/journal.pcbi.1003963','Computational','CNN','IT cortex, deep neural networks, object recognition, representational similarity','Shows that state-of-the-art CNNs match the representational geometry of primate IT cortex for object recognition, making explicit the structural equivalence between deep network feature spaces and biological visual representations.');
INSERT INTO paper (title, publication_year, journal, doi, methodology_type, ai_architecture_ref, keywords, abstract_summary) VALUES ('Deep Neural Networks Reveal a Gradient in the Complexity of Neural Representations across the Ventral Stream',2015,'Journal of Neuroscience','10.1523/JNEUROSCI.5023-14.2015','Computational','CNN','ventral stream, representational complexity, fMRI, deep learning','Uses fMRI to show that successive CNN layers predict activity in successive visual areas, mapping the computational hierarchy of the ventral stream onto deep network layer depth.');
INSERT INTO paper (title, publication_year, journal, doi, methodology_type, ai_architecture_ref, keywords, abstract_summary) VALUES ('Comparison of deep neural networks to spatio-temporal cortical dynamics of human visual object recognition reveals hierarchical correspondence',2016,'Scientific Reports','10.1038/srep27755','Computational','CNN','cortical dynamics, MEG, object recognition, temporal hierarchy, CNN layers','Uses MEG to show that CNN layers correspond not just to spatial cortical areas but to specific temporal processing stages during visual object recognition in humans.');
INSERT INTO paper (title, publication_year, journal, doi, methodology_type, ai_architecture_ref, keywords, abstract_summary) VALUES ('Using goal-driven deep learning models to understand sensory cortex',2016,'Nature Neuroscience','10.1038/nn.4244','Review','CNN','goal-driven models, sensory cortex, ventral stream, auditory cortex, review','Foundational review arguing that task-optimized deep networks trained on ethologically relevant tasks are the best current models of sensory cortical function.');
INSERT INTO paper (title, publication_year, journal, doi, methodology_type, ai_architecture_ref, keywords, abstract_summary) VALUES ('Unsupervised neural network models of the ventral visual stream',2021,'Proceedings of the National Academy of Sciences','10.1073/pnas.2014196118','Computational','CNN','unsupervised learning, ventral stream, contrastive learning, self-supervised','Shows that self-supervised contrastive learning networks achieve neural prediction accuracy in visual cortical areas matching or exceeding supervised models.');
INSERT INTO paper (title, publication_year, journal, doi, methodology_type, ai_architecture_ref, keywords, abstract_summary) VALUES ('Emergence of simple-cell receptive field properties by learning a sparse code for natural images',1996,'Nature','10.1038/381607a0','Theoretical','Sparse Autoencoder','sparse coding, V1, simple cells, receptive fields, natural images, ICA','Landmark paper showing that training a network to produce sparse representations of natural images spontaneously produces oriented localized bandpass filters identical to simple cell receptive fields in V1.');
INSERT INTO paper (title, publication_year, journal, doi, methodology_type, ai_architecture_ref, keywords, abstract_summary) VALUES ('Sparse coding with an overcomplete basis set: A strategy employed by V1?',1997,'Vision Research','10.1016/S0042-6989(97)00169-7','Theoretical','Sparse Autoencoder','sparse coding, overcomplete basis, V1, efficient coding, feature selectivity','Extends the sparse coding framework to overcomplete representations, arguing that V1 uses more basis vectors than input dimensions to achieve maximally sparse and efficient coding of natural scenes.');
INSERT INTO paper (title, publication_year, journal, doi, methodology_type, ai_architecture_ref, keywords, abstract_summary) VALUES ('The structure dilemma in biological and artificial neural networks',2021,'Scientific Reports','10.1038/s41598-021-01471-6','Computational','CNN','connectome, network structure, biological plausibility, ANN, structural comparison','Directly compares the structural properties of biological neural networks to artificial neural networks, identifying systematic differences in connectivity patterns.');
INSERT INTO paper (title, publication_year, journal, doi, methodology_type, ai_architecture_ref, keywords, abstract_summary) VALUES ('A computational architecture incorporating shallow brain networks: integrating parallel cortical and subcortical processing',2026,'Current Research in Neurobiology','10.1016/j.crneur.2026.100155','Computational','CNN','subcortical pathways, cortico-subcortical, predictive coding, decision-making, shallow networks','Presents a computational model combining cortical hierarchical processing with subcortical parallel pathways, showing that neglected subcortical-cortical interactions are necessary for explaining human perceptual decision-making behavior.');
INSERT INTO paper (title, publication_year, journal, doi, methodology_type, ai_architecture_ref, keywords, abstract_summary) VALUES ('A task-optimized neural network replicates human auditory behavior, predicts brain responses, and reveals a cortical processing hierarchy',2018,'Neuron','10.1016/j.neuron.2018.03.044','Computational','CNN','auditory cortex, task-optimized, speech recognition, cochleagram, auditory hierarchy','Demonstrates that CNNs optimized for speech and music recognition develop representations that predict neural responses along the auditory cortical hierarchy.');
INSERT INTO paper (title, publication_year, journal, doi, methodology_type, ai_architecture_ref, keywords, abstract_summary) VALUES ('Activations of deep convolutional neural networks are aligned with gamma band activity of human visual cortex',2018,'Communications Biology','10.1038/s42003-018-0110-y','Experimental','CNN','gamma oscillations, EEG, visual cortex, CNN activations, electrophysiology','Uses EEG to show that CNN layer activations correlate specifically with gamma-band neural oscillations in human visual cortex.');
INSERT INTO paper (title, publication_year, journal, doi, methodology_type, ai_architecture_ref, keywords, abstract_summary) VALUES ('Attention weights accurately predict language representations in the brain',2022,'arXiv','10.48550/arXiv.2212.01750','Computational','Transformer','attention weights, BERT, fMRI, language, brain representations, transformers','Shows that attention weights of transformer language models predict fMRI activity in language cortex, providing direct evidence that the computational attention mechanism corresponds to selective neural processing.');
INSERT INTO paper (title, publication_year, journal, doi, methodology_type, ai_architecture_ref, keywords, abstract_summary) VALUES ('Transformer brain encoders explain human high-level visual responses',2025,'arXiv','10.48550/arXiv.2501.10965','Computational','Transformer','vision transformers, visual cortex, brain encoding, high-level vision, ViT','Demonstrates that vision transformer models better explain high-level visual cortical responses than CNNs, suggesting that the attention-based architecture captures aspects of biological visual processing that convolutional architectures miss.');
INSERT INTO paper (title, publication_year, journal, doi, methodology_type, ai_architecture_ref, keywords, abstract_summary) VALUES ('Multihead self-attention in cortico-thalamic circuits',2025,'arXiv','10.48550/arXiv.2504.06354','Theoretical','Transformer','cortico-thalamic, multi-head attention, transformer, cortical columns, thalamus','Proposes and formalizes the structural correspondence between multi-head self-attention in transformers and the parallel processing channels of cortico-thalamic circuits.');
INSERT INTO paper (title, publication_year, journal, doi, methodology_type, ai_architecture_ref, keywords, abstract_summary) VALUES ('From Cognition to Computation: A Comparative Review of Human Attention and Transformer Architectures',2024,'arXiv','10.48550/arXiv.2407.01548','Review','Transformer','human attention, transformer, cognitive science, top-down, bottom-up, review','Systematically compares the cognitive neuroscience of human attention with transformer attention heads, identifying where the architectures align and where key biological features are absent.');
INSERT INTO paper (title, publication_year, journal, doi, methodology_type, ai_architecture_ref, keywords, abstract_summary) VALUES ('TransformerFAM: Feedback attention is working memory',2024,'arXiv','10.48550/arXiv.2404.09173','Computational','Transformer','working memory, feedback attention, transformer, long-context, recurrent processing','Introduces a transformer variant with feedback attention loops that create sustained activations across unlimited contexts, explicitly drawing on the neuroscience of prefrontal working memory.');
INSERT INTO paper (title, publication_year, journal, doi, methodology_type, ai_architecture_ref, keywords, abstract_summary) VALUES ('Predictive Coding or Just Feature Discovery? An Alternative Account of Why Language Models Fit Brain Data',2024,'Neurobiology of Language','10.1162/nol_a_00143','Theoretical','Transformer','predictive coding, language models, brain data, feature discovery, representational alignment','Challenges the interpretation that transformer language models fit brain data because they implement predictive coding, proposing instead that representational alignment is driven by shared feature discovery.');
INSERT INTO paper (title, publication_year, journal, doi, methodology_type, ai_architecture_ref, keywords, abstract_summary) VALUES ('Predicting brain activity using Transformers',2023,'bioRxiv','10.1101/2023.08.02.551743','Computational','Transformer','brain activity prediction, transformer, fMRI, encoding model, neural prediction','Develops transformer-based brain encoding models that predict fMRI responses to naturalistic stimuli across multiple cortical areas.');
INSERT INTO paper (title, publication_year, journal, doi, methodology_type, ai_architecture_ref, keywords, abstract_summary) VALUES ('Parallel processing of working memory and temporal information by distinct types of cortical projection neurons',2021,'Nature Communications','10.1038/s41467-021-24565-z','Experimental','RNN','working memory, prefrontal cortex, IT neurons, PT neurons, temporal information','Identifies two distinct prefrontal projection neuron types with different roles in working memory maintenance and temporal processing.');
INSERT INTO paper (title, publication_year, journal, doi, methodology_type, ai_architecture_ref, keywords, abstract_summary) VALUES ('Can sleep protect memories from catastrophic forgetting?',2020,'eLife','10.7554/eLife.51005','Computational','Continual Learning','sleep, catastrophic forgetting, memory consolidation, thalamocortical, continual learning','Demonstrates in a thalamocortical spiking network model that simulated sleep replay reverses catastrophic forgetting of old memories after new learning.');
INSERT INTO paper (title, publication_year, journal, doi, methodology_type, ai_architecture_ref, keywords, abstract_summary) VALUES ('Sleep prevents catastrophic forgetting in spiking neural networks by forming a joint synaptic weight representation',2022,'PLOS Computational Biology','10.1371/journal.pcbi.1010628','Computational','Continual Learning','spiking neural network, sleep, catastrophic forgetting, synaptic weight space, replay','Shows that sleep-like spontaneous replay in spiking networks prevents catastrophic forgetting by moving synaptic weight configurations toward manifolds that simultaneously support multiple learned tasks.');
INSERT INTO paper (title, publication_year, journal, doi, methodology_type, ai_architecture_ref, keywords, abstract_summary) VALUES ('Sleep-like unsupervised replay reduces catastrophic forgetting in artificial neural networks',2022,'Nature Communications','10.1038/s41467-022-34938-7','Computational','Continual Learning','REM sleep, unsupervised replay, continual learning, catastrophic forgetting, ANN','Proposes and validates a Sleep Replay Consolidation algorithm inspired by REM sleep dynamics, demonstrating that implementing a biological sleep phase enables continual learning of multiple tasks without accessing original training data.');
INSERT INTO paper (title, publication_year, journal, doi, methodology_type, ai_architecture_ref, keywords, abstract_summary) VALUES ('Hebbian plasticity in parallel synaptic pathways: A circuit mechanism for systems memory consolidation',2021,'PLOS Biology','10.1371/journal.pbio.3001208','Theoretical','Plastic Synaptic Weights','Hebbian plasticity, memory consolidation, parallel pathways, complementary learning systems','Proposes a circuit-level mechanism using parallel synaptic pathways with different Hebbian plasticity timescales to implement the complementary learning systems theory.');
INSERT INTO paper (title, publication_year, journal, doi, methodology_type, ai_architecture_ref, keywords, abstract_summary) VALUES ('Memory consolidation from a reinforcement learning perspective',2024,'Frontiers in Neuroscience','10.3389/fnins.2024.1331958','Review','Temporal Difference Learning','memory consolidation, reinforcement learning, hippocampus, neocortex, Dyna algorithm','Reviews the computational parallels between hippocampal-neocortical memory consolidation and the Dyna reinforcement learning architecture.');
INSERT INTO paper (title, publication_year, journal, doi, methodology_type, ai_architecture_ref, keywords, abstract_summary) VALUES ('Memory-Augmented Transformers: A Systematic Review from Neuroscience Principles to Technical Solutions',2025,'arXiv','10.48550/arXiv.2508.10824','Review','Transformer','memory-augmented transformers, neuroscience, working memory, hippocampus, long-term memory','Systematically reviews how neuroscience memory principles have been incorporated into transformer architectures.');
INSERT INTO paper (title, publication_year, journal, doi, methodology_type, ai_architecture_ref, keywords, abstract_summary) VALUES ('RippleNet: A Recurrent Neural Network for Sharp Wave Ripple Detection',2021,'Frontiers in Neuroscience','10.3389/fnins.2021.685490','Computational','RNN','sharp wave ripples, hippocampus, RNN, memory replay, detection','Uses a recurrent neural network to detect hippocampal sharp wave ripples, the electrophysiological signature of memory replay events.');
INSERT INTO paper (title, publication_year, journal, doi, methodology_type, ai_architecture_ref, keywords, abstract_summary) VALUES ('Barcode activity in a recurrent network model of the hippocampus enables efficient memory binding',2025,'eLife','10.7554/eLife.104921','Computational','RNN','hippocampus, barcode activity, pattern separation, memory binding, recurrent network','Proposes barcode-like sparse activity patterns in hippocampal circuits as a mechanism for unique memory indexing.');
INSERT INTO paper (title, publication_year, journal, doi, methodology_type, ai_architecture_ref, keywords, abstract_summary) VALUES ('Differentiable plasticity: training plastic neural networks with backpropagation',2018,'Proceedings of ICML','10.48550/arXiv.1804.02464','Computational','Plastic Synaptic Weights','differentiable plasticity, Hebbian learning, meta-learning, fast weights, backpropagation','Introduces differentiable plasticity: networks learn both fixed weights via gradient descent and plastic Hebbian connections that update during inference, directly bridging biological Hebbian learning and gradient-based AI training.');
INSERT INTO paper (title, publication_year, journal, doi, methodology_type, ai_architecture_ref, keywords, abstract_summary) VALUES ('Self-backpropagation of synaptic modifications elevates the efficiency of spiking and artificial neural networks',2021,'Science Advances','10.1126/sciadv.abh0451','Theoretical','Backpropagation','self-backpropagation, synaptic plasticity, biologically plausible, STDP, local learning','Proposes a biologically plausible learning rule called self-backpropagation in which synaptic modifications propagate backward through dendritic compartments without a global error signal.');
INSERT INTO paper (title, publication_year, journal, doi, methodology_type, ai_architecture_ref, keywords, abstract_summary) VALUES ('Somato-dendritic synaptic plasticity and error-backpropagation in active dendrites',2016,'PLOS Computational Biology','10.1371/journal.pcbi.1004638','Theoretical','Backpropagation','dendritic computation, somatic-dendritic, backpropagation, calcium spikes, two-compartment model','Demonstrates that dendritic calcium spikes in a two-compartment neuron model implement a biologically plausible form of error backpropagation.');
INSERT INTO paper (title, publication_year, journal, doi, methodology_type, ai_architecture_ref, keywords, abstract_summary) VALUES ('Neuroscience-inspired online unsupervised learning algorithms',2019,'arXiv','10.48550/arXiv.1908.01867','Theoretical','Backpropagation','similarity-based learning, unsupervised, biologically plausible, Hebbian, online learning','Develops a family of biologically plausible similarity-based unsupervised learning algorithms that can learn useful representations without backpropagation or labeled data.');
INSERT INTO paper (title, publication_year, journal, doi, methodology_type, ai_architecture_ref, keywords, abstract_summary) VALUES ('Bridging Brains and Machines: A Unified Frontier in Neuroscience, Artificial Intelligence, and Neuromorphic Systems',2025,'arXiv','10.48550/arXiv.2503.01735','Review','Mixed','neuromorphic, neuro-AI, spiking networks, brain-machine interface, review','Comprehensive review mapping the current state of the neuro-AI intersection across computational neuroscience, AI architecture, and neuromorphic hardware.');
INSERT INTO paper (title, publication_year, journal, doi, methodology_type, ai_architecture_ref, keywords, abstract_summary) VALUES ('The brain as a blueprint: a survey of brain-inspired approaches to learning in artificial intelligence',2025,'arXiv','10.48550/arXiv.2511.04455','Review','Mixed','brain-inspired AI, synaptic plasticity, error propagation, continual learning, survey','Surveys successful implementations of brain-inspired learning principles in deep learning, identifying where biological discoveries could drive the next generation of AI learning algorithms.');
INSERT INTO paper (title, publication_year, journal, doi, methodology_type, ai_architecture_ref, keywords, abstract_summary) VALUES ('Model-based inference of synaptic plasticity rules',2024,'bioRxiv','10.1101/2024.07.23.604840','Computational','Backpropagation','synaptic plasticity rules, model-based inference, STDP, learning rule identification','Develops a framework for inferring synaptic plasticity rules from observed neural data, enabling systematic comparison between biological plasticity and gradient-based learning rules.');
INSERT INTO paper (title, publication_year, journal, doi, methodology_type, ai_architecture_ref, keywords, abstract_summary) VALUES ('A deep learning framework for neuroscience',2019,'Nature Neuroscience','10.1038/s41593-019-0520-2','Review','Mixed','deep learning, neuroscience framework, credit assignment, optimization, biological plausibility','Proposes a unified framework for using deep learning concepts to understand brain computation, covering credit assignment, optimization objectives, and architectural constraints. Authored by Richards, Lillicrap, and Bengio.');
INSERT INTO paper (title, publication_year, journal, doi, methodology_type, ai_architecture_ref, keywords, abstract_summary) VALUES ('Recent Advances at the Interface of Neuroscience and Artificial Neural Networks',2022,'Journal of Neuroscience','10.1523/JNEUROSCI.1503-22.2022','Review','Mixed','neuromodulation, recurrent networks, CNNs, neuro-AI interface, review','Reviews recent findings at the neuroscience-AI intersection with focus on neuromodulatory systems and their implications for designing context-sensitive AI architectures.');
INSERT INTO paper (title, publication_year, journal, doi, methodology_type, ai_architecture_ref, keywords, abstract_summary) VALUES ('Emergence of sparse coding, balance and decorrelation from a biologically-grounded spiking neural network model of V1',2025,'PLOS Computational Biology','10.1371/journal.pcbi.1013644','Computational','Sparse Autoencoder','V1, spiking network, sparse coding, E/I balance, decorrelation, receptive fields','Shows that a biologically realistic spiking network model with excitatory-inhibitory balance spontaneously develops sparse coding and orientation-selective receptive fields matching experimental V1 data.');
INSERT INTO paper (title, publication_year, journal, doi, methodology_type, ai_architecture_ref, keywords, abstract_summary) VALUES ('A neural substrate of prediction and reward',1997,'Science','10.1126/science.275.5306.1593','Experimental','Temporal Difference Learning','dopamine, reward prediction error, temporal difference, conditioning, reinforcement learning','Foundational paper demonstrating that primate dopamine neurons signal reward prediction errors exactly as predicted by the temporal difference reinforcement learning algorithm.');
INSERT INTO paper (title, publication_year, journal, doi, methodology_type, ai_architecture_ref, keywords, abstract_summary) VALUES ('Dopamine reward prediction error coding',2016,'Dialogues in Clinical Neuroscience','10.31887/DCNS.2016.18.1/wschultz','Review','Temporal Difference Learning','dopamine, reward prediction error, TD learning, economic utility, addiction','Comprehensive review of two decades of work establishing dopamine neurons as a biological implementation of temporal difference error coding.');
INSERT INTO paper (title, publication_year, journal, doi, methodology_type, ai_architecture_ref, keywords, abstract_summary) VALUES ('Active Predictive Coding: A Unifying Neural Model for Active Perception, Compositional Learning, and Hierarchical Planning',2024,'Neural Computation','10.1162/neco_a_01672','Theoretical','Predictive Coding Network','active inference, predictive coding, hierarchical planning, compositional learning, active perception','Extends the predictive coding framework to active inference, showing how a hierarchical predictive coding network can unify perception, learning, and action planning.');
INSERT INTO paper (title, publication_year, journal, doi, methodology_type, ai_architecture_ref, keywords, abstract_summary) VALUES ('Toward an integration of deep learning and neuroscience',2016,'Frontiers in Computational Neuroscience','10.3389/fncom.2016.00094','Theoretical','Mixed','deep learning, neuroscience, cost functions, credit assignment, modularity','Systematic analysis of how neuroscience-inspired cost functions, credit assignment methods, and modular architectural constraints could be incorporated into deep learning.');
INSERT INTO paper (title, publication_year, journal, doi, methodology_type, ai_architecture_ref, keywords, abstract_summary) VALUES ('Neuroscience-inspired artificial intelligence',2017,'Neuron','10.1016/j.neuron.2017.06.011','Review','Mixed','neuroscience, AI, DeepMind, attention, memory, reinforcement learning, review','Influential DeepMind review of how neuroscience has historically contributed to AI breakthroughs and how the next generation could benefit from attention, episodic memory, and continual learning principles.');
INSERT INTO paper (title, publication_year, journal, doi, methodology_type, ai_architecture_ref, keywords, abstract_summary) VALUES ('A critique of pure learning and what artificial neural networks can learn from animal brains',2019,'Nature Communications','10.1038/s41467-019-11786-6','Theoretical','Mixed','inductive biases, genomic bottleneck, animal brains, learning efficiency, innate structure','Argues that AI relies too heavily on learning from experience and neglects innate structure encoded in the genome, proposing that AI should incorporate biologically-inspired inductive biases.');
INSERT INTO paper (title, publication_year, journal, doi, methodology_type, ai_architecture_ref, keywords, abstract_summary) VALUES ('Building machines that learn and think like people',2017,'Behavioral and Brain Sciences','10.1017/S0140525X16001837','Theoretical','Mixed','human cognition, causal models, compositional representations, learning to learn, Bayesian','Argues that AI systems should incorporate intuitive physics, intuitive psychology, causal models, and compositional representations, drawing on cognitive science as a blueprint.');
INSERT INTO paper (title, publication_year, journal, doi, methodology_type, ai_architecture_ref, keywords, abstract_summary) VALUES ('Catalyzing next-generation artificial intelligence through NeuroAI',2023,'Nature Communications','10.1038/s41467-023-37180-x','Review','Mixed','NeuroAI, embodied Turing test, sensorimotor, next-generation AI, research agenda','Manifesto signed by 27 leading neuro-AI researchers proposing the embodied Turing test as the benchmark for NeuroAI progress.');
INSERT INTO paper (title, publication_year, journal, doi, methodology_type, ai_architecture_ref, keywords, abstract_summary) VALUES ('NeuroAI and Beyond: Bridging Between Advances in Neuroscience and Artificial Intelligence',2025,'arXiv','10.48550/arXiv.2604.18637','Review','Mixed','NeuroAI, capability gaps, energy efficiency, physical interaction, multi-scale learning','Identifies three fundamental capability gaps in current AI and maps the neuroscience principles that address each, presenting a research roadmap for NeuroAI.');
INSERT INTO paper (title, publication_year, journal, doi, methodology_type, ai_architecture_ref, keywords, abstract_summary) VALUES ('A Computational Perspective on NeuroAI and Synthetic Biological Intelligence',2025,'arXiv','10.48550/arXiv.2509.23896','Review','Mixed','synthetic biological intelligence, neuromorphic, predictive coding, active inference, brain organoids','Reviews computational frameworks at the neuro-AI interface including predictive coding, active inference, and neuromorphic computing, with attention to emerging synthetic biological intelligence research.');
